import{_ as s,c as i,o as t,ag as a}from"./chunks/framework.Ci10AEOF.js";const g=JSON.parse('{"title":"Building from Source","description":"Compiling Open Integration Engine with Gradle, creating the development database, and running the server you just built","frontmatter":{"title":"Building from Source","description":"Compiling Open Integration Engine with Gradle, creating the development database, and running the server you just built"},"headers":[],"relativePath":"engine/building_from_source.md","filePath":"engine/building_from_source.md","lastUpdated":1793057853000}'),n={name:"engine/building_from_source.md"};function r(o,e,h,d,l,p){return t(),i("div",null,e[0]||(e[0]=[a(`<h1 id="building-from-source" tabindex="-1">Building from Source <a class="header-anchor" href="#building-from-source" aria-label="Permalink to &quot;Building from Source&quot;">​</a></h1><p>This page is for contributors who want to compile the engine and run what they compiled. If you only want a working server, install a published release instead: see <a href="./installation.html">Installation</a>. Nothing here is required to use OIE.</p><p>The build is driven by Gradle through a wrapper committed to the repository, so the only thing you have to install yourself is a JDK.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><h3 id="java" tabindex="-1">Java <a class="header-anchor" href="#java" aria-label="Permalink to &quot;Java&quot;">​</a></h3><p>The repository pins the JDK it is built against in <a href="https://github.com/OpenIntegrationEngine/engine/blob/main/.sdkmanrc" target="_blank" rel="noreferrer"><code>.sdkmanrc</code></a> at the root of the tree. At the time of writing that is a Java 17 Zulu build with JavaFX included, and the JavaFX part matters when you run the Administrator client. The client compiles on a plain JDK, because the repository carries the JavaFX classes it compiles against.</p><p>The least error-prone way to get exactly that JDK is <a href="https://sdkman.io/" target="_blank" rel="noreferrer">SDKMAN</a>, which reads the pin for you:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://get.sdkman.io&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>Open a new shell afterwards so the <code>sdk</code> command is on your path.</p><h3 id="gradle" tabindex="-1">Gradle <a class="header-anchor" href="#gradle" aria-label="Permalink to &quot;Gradle&quot;">​</a></h3><p>You do not install Gradle. The <code>gradlew</code> script in the repository root downloads and runs the correct version on first use.</p><div class="tip custom-block"><p class="custom-block-title">Windows</p><p>Every command below is written as <code>./gradlew</code>. On Windows use <code>gradlew.bat</code> instead. If the build stops in the javadoc step complaining that a path is too long, add <code>-x :server:userApiJavadoc</code> to skip it.</p></div><h2 id="get-the-source" tabindex="-1">Get the source <a class="header-anchor" href="#get-the-source" aria-label="Permalink to &quot;Get the source&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/OpenIntegrationEngine/engine.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> engine</span></span></code></pre></div><p>Then let SDKMAN install and select the pinned JDK. Run this from the repository root, where <code>.sdkmanrc</code> lives:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p><code>sdk env install</code> installs the pinned version if you do not have it and switches the current shell to it. In a new shell, run <code>sdk env</code> to switch again without reinstalling. Confirm you got what you expected before building:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span></span></code></pre></div><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -PdisableSigning=true</span></span></code></pre></div><p><code>-PdisableSigning=true</code> turns off jar signing. Without it the build signs with a self-signed development certificate kept in the repository, so no key of yours is needed. Signing is slow, though, and contacts a timestamp service over the network. Leave it off for local work.</p><p>The first run downloads the Gradle distribution and every dependency, so expect several minutes. Later runs are much faster. A successful build ends with <code>BUILD SUCCESSFUL</code> and leaves a complete server layout in <code>server/setup</code>.</p><p>A few other targets are useful once you are working in the tree:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -PdisableSigning=true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # unit tests only</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Dependencies are checksum-verified</p><p>Versions are pinned in <code>gradle/libs.versions.toml</code> and their checksums are recorded. Editing a version means regenerating that metadata, and it has to be done against a cold dependency cache or the result passes locally and fails in CI. <a href="https://github.com/OpenIntegrationEngine/engine/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> has the exact command.</p></div><h2 id="development-database" tabindex="-1">Development database <a class="header-anchor" href="#development-database" aria-label="Permalink to &quot;Development database&quot;">​</a></h2><p>You do not need to create or reset the database — but do not expect it to keep anything either. Every build deletes the embedded Derby database: the <code>stageSetup</code> task wipes <code>setup/appdata</code>, which is where it lives. On the next startup the server notices it is gone and recreates the database and its schema automatically. No manual action is needed, and any channels or messages you saved locally do not survive a build.</p><h2 id="run-the-server" tabindex="-1">Run the server <a class="header-anchor" href="#run-the-server" aria-label="Permalink to &quot;Run the server&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">server/setup/oieserver</span></span></code></pre></div><p><code>oieserver</code> is the launcher script the build stages into <code>server/setup</code> for running the engine out of your working tree. (A production installation starts through a launcher generated by install4j, so this is not the production entry point.) It changes to its own directory first, so you can run it from the repository root. It runs in the foreground and streams the log to your terminal. Stop it with <code>Ctrl+C</code>.</p><p>You can also start the same staged server through Gradle:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :server:devLauncher</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -PdisableSigning=true</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title"><code>:server:devRun</code> does not currently work</p><p><code>CONTRIBUTING.md</code> also lists <code>:server:devRun</code>, which runs the server straight from the compiled classes rather than from <code>server/setup</code>. On current <code>main</code> it fails at startup with <code>Could not find resource SqlMapConfig.xml</code> and then retries startup twice, 10 seconds apart, before aborting, because the <code>dbconf</code> directory that holds that file is packaged into the distribution but is not on the task&#39;s classpath. The reporter closed <a href="https://github.com/OpenIntegrationEngine/engine/issues/416" target="_blank" rel="noreferrer">engine issue #416</a> after finding that <code>:server:devLauncher</code> works, and <code>:server:devRun</code> itself still fails. Use <code>server/setup/oieserver</code> until it is fixed.</p></div><p>A successful startup ends with lines like these. Versions, addresses and dates will differ:</p><div class="language-log vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [Main Server Thread] </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">com.mirth.connect.server.Mirth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Open Integration Engine </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (Built on ...) server successfully started.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [Main Server Thread] </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">com.mirth.connect.server.Mirth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Running OpenJDK </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-Bit Server VM </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">17</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">17</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> on Mac OS X (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, aarch64), derby, with charset UTF-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [Main Server Thread] </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">com.mirth.connect.server.Mirth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Web server running at </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">http://&lt;host&gt;:8080/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> and </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">https://&lt;host&gt;:8443/</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Stop any other engine first</p><p>The server binds ports 8080 and 8443. If you already have OIE running as a service, or a container publishing those ports, start nothing until you have stopped it. A second engine logs <code>http.port port is already in use: 8080</code> and <code>https.port port is already in use: 8443</code> and does not serve, but its process keeps running while the first engine keeps answering, so you can end up administering the wrong one without noticing.</p></div><h3 id="first-login" tabindex="-1">First login <a class="header-anchor" href="#first-login" aria-label="Permalink to &quot;First login&quot;">​</a></h3><p>Scan the startup log for the initial administrator password. A new database prints it once, in a banner near the top of the output:</p><div class="language-log vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">WARN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [Main Server Thread] </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">com.mirth.connect.server.Mirth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">********************************************************************************</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">************   Initial admin password is &lt;generated&gt;            ************</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">********************************************************************************</span></span></code></pre></div><p>The username is <code>admin</code>. To choose the password yourself instead, set <code>server.initialadminpassword</code> in <code>server/setup/conf/mirth.properties</code> before the first startup. The file already contains an empty <code>server.initialadminpassword =</code> entry, so set that line rather than appending a second one, then start the server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">perl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/^server\\.initialadminpassword\\s*=.*/server.initialadminpassword = admin/&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server/setup/conf/mirth.properties</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">server/setup/oieserver</span></span></code></pre></div><p>The property is read only when the database is first created; if it is left empty, the server generates a password and prints it in the banner above.</p><h2 id="connect-to-it" tabindex="-1">Connect to it <a class="header-anchor" href="#connect-to-it" aria-label="Permalink to &quot;Connect to it&quot;">​</a></h2><p>Open <code>https://localhost:8443/</code> in a browser. The server presents a certificate signed by the engine&#39;s own generated certificate authority, so you will have to accept a warning the first time. You should land on the engine&#39;s status page, which links to the launcher documentation and the client API.</p><p>From there, <a href="./accessing_the_administrator.html">Accessing the Administrator</a> covers the browser-based administrator and the desktop Administrator&#39;s launcher.</p><p>The Gradle build also exposes <code>:client:devClient</code>, which launches the desktop Administrator from the tree you just compiled. It connects to <code>https://localhost:8443</code> and will only reach the server you intended if nothing else is bound to that port.</p><h2 id="what-is-in-the-tree" tabindex="-1">What is in the tree <a class="header-anchor" href="#what-is-in-the-tree" aria-label="Permalink to &quot;What is in the tree&quot;">​</a></h2><p>The repository is a multi-module Gradle build. The modules, as declared in <code>settings.gradle</code>:</p><table tabindex="0"><thead><tr><th>Directory</th><th>What it is</th></tr></thead><tbody><tr><td><code>server</code></td><td>The engine itself: server source, the core jars, and the staged distribution under <code>server/setup</code>.</td></tr><tr><td><code>client</code></td><td>The Swing Administrator client and the client half of each bundled extension.</td></tr><tr><td><code>donkey</code></td><td>The message engine underneath the server.</td></tr><tr><td><code>command</code></td><td>The command line client.</td></tr><tr><td><code>generator</code></td><td>HL7 vocabulary generator tooling. Not part of the distribution build.</td></tr><tr><td><code>smoketest</code></td><td>Integration tests that run against a live server, not unit tests.</td></tr></tbody></table><p>Two directories outside the module list are worth knowing: <code>gradle</code> holds the version catalog and dependency verification metadata, and <code>ci</code> holds the scripts the pipelines run.</p><h2 id="working-in-an-ide" tabindex="-1">Working in an IDE <a class="header-anchor" href="#working-in-an-ide" aria-label="Permalink to &quot;Working in an IDE&quot;">​</a></h2><p>Import the repository as a Gradle project. IntelliJ IDEA handles this natively; Eclipse does it through Buildship. The old <code>.classpath</code> and <code>.project</code> files were removed deliberately, so do not go looking for them.</p><p>To attach a debugger, add <code>--debug-jvm</code> to any of the run targets. The JVM suspends at startup and waits for a connection on port 5005.</p>`,53)]))}const u=s(n,[["render",r]]);export{g as __pageData,u as default};
